"use strict";
/* Phase 33 (optional) — REAL browser check of the web viewer path.
 * Not part of the static harness; skips cleanly when Edge or ffmpeg is absent.
 *
 * It verifies, with evidence instead of assumptions:
 *  1. HLS fixture generated by real ffmpeg using hlsPackager's codec profile
 *     (baseline H264 + AAC, 2s MPEG-TS segments).
 *  2. Playlist + segments are fetchable through the SAME Express /live static
 *     route configuration the production API serves on Railway's PORT
 *     (CORS *, application/vnd.apple.mpegurl / video/mp2t content types).
 *  3. The exported web app (mobile/dist) actually boots and renders in a
 *     real Chromium browser (Vercel readiness beyond "export succeeded").
 *  4. A cross-origin probe assigns the m3u8 URL to a native <video> element —
 *     the exact mechanism expo-video's web build uses (VideoPlayer.web.js:
 *     video.setAttribute('src', uri); no hls.js anywhere in the dependency).
 *     Outcomes are RECORDED as facts: Chromium not decoding HLS natively is a
 *     documented limitation, not a script failure.
 *
 * Run: node validation/phase33/browser-hls-check.js
 */
const fs = require("fs");
const http = require("http");
const os = require("os");
const path = require("path");
const { spawn, execFileSync } = require("child_process");

const ROOT = path.resolve(__dirname, "..", "..");
const FFMPEG_CANDIDATES = [
  process.env.FFMPEG_PATH,
  "C:\\ffmpeg\\bin\\ffmpeg.exe",
  "/usr/bin/ffmpeg",
].filter(Boolean);
const EDGE_CANDIDATES = [
  process.env.EDGE_PATH,
  "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
  "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe",
  "/usr/bin/microsoft-edge",
].filter(Boolean);

function skip(msg) {
  console.log(`SKIP  ${msg}`);
  console.log("\nPhase 33 browser check: SKIPPED");
}
function findFirst(paths) { return paths.find((p) => { try { return fs.existsSync(p); } catch (_e) { return false; } }); }

function makeMediaServer(liveDir) {
  const express = require(path.join(ROOT, "server", "node_modules", "express"));
  const app = express();
  // Mirrors server/src/index.js /live middleware (CORS + content types).
  app.use("/live", (req, res, next) => {
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET, HEAD, OPTIONS");
    if (req.method === "OPTIONS") return res.sendStatus(204);
    next();
  });
  app.use("/live", express.static(path.join(liveDir, ".."), {
    fallthrough: true,
    setHeaders(res, filePath) {
      if (filePath.endsWith(".m3u8")) {
        res.setHeader("Content-Type", "application/vnd.apple.mpegurl");
        res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
      } else if (filePath.endsWith(".ts")) {
        res.setHeader("Content-Type", "video/mp2t");
        res.setHeader("Cache-Control", "public, max-age=60");
      }
    },
  }));
  app.use("/live", (req, res) => res.status(404).send("not found"));
  return app;
}

function makeStaticServer(rootDir) {
  const express = require(path.join(ROOT, "server", "node_modules", "express"));
  const app = express();
  app.use(express.static(rootDir));
  return app;
}


function listen(app) {
  return new Promise((resolve, reject) => {
    const srv = app.listen(0, "127.0.0.1", () => resolve(srv));
    srv.on("error", reject);
  });
}
function portOf(srv) { return srv.address().port; }

function generateFixture(ffmpeg, outDir) {
  // INPUT side: a local lavfi file (the packager's real input is RTMP, where
  // -rtmp_live is valid; it is stripped for file input).
  // OUTPUT side: the packager's EXACT argv (hlsPackager.buildArgs) so the
  // fixture playlist/segments are representative of what production writes.
  fs.mkdirSync(outDir, { recursive: true });
  const tmpSrc = path.join(path.dirname(outDir), "src.mp4");
  execFileSync(ffmpeg, [
    "-hide_banner", "-loglevel", "error",
    "-f", "lavfi", "-i", "testsrc=size=640x360:rate=30",
    "-f", "lavfi", "-i", "sine=frequency=440",
    "-t", "8", "-map", "0:v:0", "-map", "1:a:0",
    "-c:v", "libx264", "-preset", "veryfast", "-profile:v", "baseline",
    "-pix_fmt", "yuv420p", "-g", "60", "-keyint_min", "60",
    "-c:a", "aac", "-ar", "44100", "-ac", "1", "-b:a", "64k",
    tmpSrc,
  ], { stdio: "pipe" });
  const pack = require(path.join(ROOT, "server", "src", "streaming", "hlsPackager"));
  const playlist = path.join(outDir, "index.m3u8");
  const full = pack.buildArgs({ ffmpegInput: tmpSrc, outDir, playlist });
  const args = [];
  for (let i = 0; i < full.length; i++) {
    if (full[i] === "-rtmp_live") { i++; continue; } // RTMP-only input option
    args.push(full[i]);
  }
  execFileSync(ffmpeg, args, { stdio: "pipe" });
  const files = fs.readdirSync(outDir);
  const segs = files.filter((f) => f.endsWith(".ts"));
  const text = fs.readFileSync(playlist, "utf8");
  if (!/#EXTM3U/.test(text) || !/#EXTINF/.test(text) || segs.length < 2) {
    throw new Error(`fixture incomplete: extinf=${/#EXTINF/.test(text)} segs=${segs.length}`);
  }
  if (/master_pl/i.test(args.join(" "))) throw new Error("packager argv unexpectedly contains master_pl");
  return { playlist: "index.m3u8", segments: segs };
}

/* ---- minimal Chrome DevTools Protocol client over ws ---- */
function connectCdp(wsUrl) {
  const WebSocket = require(path.join(ROOT, "server", "node_modules", "ws"));
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    let nextId = 1;
    const pending = new Map();
    const listeners = [];
    ws.on("message", (raw) => {
      let msg; try { msg = JSON.parse(String(raw)); } catch (_e) { return; }
      if (msg.id && pending.has(msg.id)) {
        const { res, rej } = pending.get(msg.id);
        pending.delete(msg.id);
        if (msg.error) rej(new Error(msg.error.message)); else res(msg.result);
      } else if (msg.method) listeners.forEach((fn) => fn(msg));
    });
    ws.on("open", () => resolve({
      send(method, params) {
        const id = nextId++;
        return new Promise((res, rej) => {
          pending.set(id, { res, rej });
          ws.send(JSON.stringify({ id, method, params: params || {} }));
          setTimeout(() => { if (pending.has(id)) { pending.delete(id); rej(new Error(`cdp timeout: ${method}`)); } }, 15000);
        });
      },
      on(fn) { listeners.push(fn); },
      close() { try { ws.close(); } catch (_e) { /* ignore */ } },
    }));
    ws.on("error", reject);
  });
}

async function launchEdge(edgePath) {
  const port = 9300 + Math.floor(Math.random() * 400);
  const udd = fs.mkdtempSync(path.join(os.tmpdir(), "p33-edge-"));
  const child = spawn(edgePath, [
    "--headless=new", "--disable-gpu", "--no-first-run", "--no-default-browser-check",
    "--disable-extensions", "--mute-audio", "--autoplay-policy=no-user-gesture-required",
    `--remote-debugging-port=${port}`, `--user-data-dir=${udd}`, "about:blank",
  ], { stdio: "ignore", detached: false });
  for (let i = 0; i < 40; i++) {
    await new Promise((r) => setTimeout(r, 500));
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/list`);
      const targets = await res.json();
      const page = targets.find((t) => t.type === "page" && t.webSocketDebuggerUrl);
      if (page) return { child, port, udd, page };
    } catch (_e) { /* not up yet */ }
  }
  throw new Error("Edge CDP did not come up");
}

async function evaluate(cdp, expression) {
  const out = await cdp.send("Runtime.evaluate", { expression, returnByValue: true });
  return out && out.result ? out.result.value : null;
}

async function runProbe(cdp, url, doneExpr, timeoutMs) {
  const errors = [];
  cdp.on((msg) => {
    if (msg.method === "Runtime.exceptionThrown") {
      const d = msg.params && msg.params.exceptionDetails;
      errors.push(String((d && d.text) || "exception"));
    }
  });
  await cdp.send("Page.navigate", { url });
  const started = Date.now();
  let value = null;
  while (Date.now() - started < timeoutMs) {
    await new Promise((r) => setTimeout(r, 500));
    value = await evaluate(cdp, doneExpr);
    if (value) break;
  }
  return { value, errors };
}

const PROBE_HTML = `<!doctype html><html><head><meta charset="utf-8"><title>phase33 probe</title></head>
<body><div id="root">probe</div><script>
(function () {
  var params = new URLSearchParams(location.search);
  var mediaUrl = params.get("media");
  var mode = params.get("mode") || "hls";
  var p = { done: false, mode: mode };
  function finish() { p.done = true; }
  if (mode === "app") {
    setTimeout(function () {
      p.textLen = (document.body.innerText || "").length;
      p.textSample = (document.body.innerText || "").slice(0, 120);
      p.childCount = document.body.childElementCount;
      finish();
    }, 7000);
  } else {
    fetch(mediaUrl, { cache: "no-store" })
      .then(function (r) {
        p.fetch = { status: r.status, type: r.headers.get("content-type"), acao: r.headers.get("access-control-allow-origin") };
        return r.text();
      })
      .then(function (t) {
        p.fetch.playlistOk = /#EXTM3U/.test(t) && /#EXTINF/.test(t);
        var m = t.match(/[\\w.-]+\\.ts/);
        if (!m) { finish(); return; }
        return fetch(mediaUrl.replace(/[^/]+$/, m[0]), { cache: "no-store" })
          .then(function (r2) { p.fetch.segment = { status: r2.status, type: r2.headers.get("content-type") }; return r2.arrayBuffer(); })
          .then(function (buf) { p.fetch.segment.bytes = buf.byteLength; finish(); });
      })
      .catch(function (e) { p.fetch = { error: String(e) }; finish(); });

    var v = document.createElement("video");
    v.muted = true; v.autoplay = true; v.playsInline = true;
    v.addEventListener("loadedmetadata", function () { p.video = { event: "loadedmetadata", w: v.videoWidth, h: v.videoHeight }; });
    v.addEventListener("playing", function () { p.video = { event: "playing", t: v.currentTime, w: v.videoWidth, h: v.videoHeight }; finish(); });
    v.addEventListener("error", function () { p.video = { event: "error", code: v.error && v.error.code, msg: v.error && v.error.message }; });
    v.src = mediaUrl;
    document.body.appendChild(v);
    v.play().catch(function (e) { if (!p.video) p.video = { event: "play-rejected", msg: String(e) }; });
    setTimeout(function () { if (!p.video) p.video = { event: "timeout" }; finish(); }, 9000);
  }
  var iv = setInterval(function () { if (p.done) { clearInterval(iv); window.__PROBE__ = p; } }, 250);
  setTimeout(function () { window.__PROBE__ = p; }, 11000);
})();
</script></body></html>`;

function skipExit(msg) { skip(msg); process.exit(0); }

async function main() {
  const ffmpeg = findFirst(FFMPEG_CANDIDATES);
  if (!ffmpeg) return skipExit("ffmpeg not found (set FFMPEG_PATH) — cannot generate HLS fixture");
  const edgePath = findFirst(EDGE_CANDIDATES);
  if (!edgePath) return skipExit("Edge/Chromium not found (set EDGE_PATH) — cannot run real-browser probes");
  const distDir = path.join(ROOT, "mobile", "dist");
  if (!fs.existsSync(path.join(distDir, "index.html"))) {
    return skipExit("web export absent — run: cd mobile && npx expo export --platform web");
  }

  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "p33-fixture-"));
  const key = "d".repeat(48);
  const liveKeyDir = path.join(tmp, "live", key);
  const fixture = generateFixture(ffmpeg, liveKeyDir);
  console.log(`fixture: ${fixture.segments.length} TS segments + ${fixture.playlist} (baseline H264+AAC)`);

  const mediaSrv = await listen(makeMediaServer(liveKeyDir));
  const distSrv = await listen(makeStaticServer(distDir));
  const probeSrv = await new Promise((resolve, reject) => {
    const s = http.createServer((req, res) => {
      if (String(req.url || "").startsWith("/probe.html")) {
        res.setHeader("Content-Type", "text/html; charset=utf-8");
        res.setHeader("Cache-Control", "no-store");
        return res.end(PROBE_HTML);
      }
      res.statusCode = 404; res.end("not found");
    });
    s.on("error", reject);
    s.listen(0, "127.0.0.1", () => resolve(s));
  });

  const results = [];
  const record = (name, pass, detail) => {
    results.push({ name, pass: !!pass });
    console.log(`${pass ? "PASS" : "FAIL"}  ${name}${detail ? ` — ${detail}` : ""}`);
  };
  const fact = (name, detail) => console.log(`INFO  ${name} — ${detail}`);

  let edge = null; let cdp = null;
  try {
    edge = await launchEdge(edgePath);
    cdp = await connectCdp(edge.page.webSocketDebuggerUrl);
    await cdp.send("Runtime.enable");
    await cdp.send("Page.enable");

    /* ---- Probe 1: exported web app boots in a real browser ---- */
    const appUrl = `http://127.0.0.1:${portOf(distSrv)}/`;
    const appDoneExpr = `(function(){var t=(document.body.innerText||"").length;return t>0?JSON.stringify({textLen:t,children:document.body.childElementCount,sample:document.body.innerText.slice(0,120)}):null;})()`;
    const appProbe = await runProbe(cdp, appUrl, appDoneExpr, 15000);
    let appData = appProbe.value ? JSON.parse(appProbe.value) : null;
    if (!appData) {
      const finalState = await evaluate(cdp, `JSON.stringify({textLen:(document.body.innerText||"").length,children:document.body.childElementCount})`);
      appData = finalState ? JSON.parse(finalState) : null;
    }
    record("exported web app boots and renders in headless Chromium",
      Boolean(appData && appData.textLen > 0),
      appData ? `textLen=${appData.textLen} children=${appData.children}${appData.sample ? ` sample=${JSON.stringify(appData.sample.slice(0, 60))}` : ""}` : "no DOM");
    if (appProbe.errors.length) fact("app boot JS exceptions (network/API failures expected offline)", appProbe.errors.slice(0, 3).join(" | "));

    /* ---- Probe 2: cross-origin HLS fetch + native <video> decode ---- */
    const mediaUrl = `http://127.0.0.1:${portOf(mediaSrv)}/live/${key}/${fixture.playlist}`;
    const probeUrl = `http://127.0.0.1:${portOf(probeSrv)}/probe.html?mode=hls&media=${encodeURIComponent(mediaUrl)}`;
    const hlsProbe = await runProbe(cdp, probeUrl,
      "window.__PROBE__ && window.__PROBE__.done ? JSON.stringify(window.__PROBE__) : null", 20000);
    const hls = hlsProbe.value ? JSON.parse(hlsProbe.value) : null;
    const f = (hls && hls.fetch) || {};
    // NOTE: browsers deliberately hide Access-Control-Allow-Origin from JS
    // (not a CORS-safelisted response header), so f.acao is always null.
    // A successful cross-origin fetch() in CORS mode IS the browser-enforced
    // proof that the ACAO header was present and correct.
    record("playlist readable cross-origin in browser (browser-enforced CORS + content type)",
      f.status === 200 && /mpegurl/.test(String(f.type)) && f.playlistOk === true,
      `status=${f.status} type=${f.type} playlistOk=${f.playlistOk} (acao hidden-by-design=${f.acao === null || f.acao === undefined})`);
    record("segment fetchable (video/mp2t, non-empty)",
      f.segment && f.segment.status === 200 && /mp2t/.test(String(f.segment.type)) && f.segment.bytes > 0,
      f.segment ? `status=${f.segment.status} type=${f.segment.type} bytes=${f.segment.bytes}` : "missing");
    const v = (hls && hls.video) || {};
    if (v.event === "playing" || v.event === "loadedmetadata") {
      fact("native <video> decoded the HLS URL in this browser", JSON.stringify(v));
    } else {
      fact("native <video> did NOT play the m3u8 in this Chromium build (EXPECTED: Chromium has no native HLS; expo-video web sets video.src directly with no hls.js — Safari/iOS plays natively, desktop Chrome/Edge/Firefox need an MSE player such as hls.js)",
        JSON.stringify(v));
    }
    if (hlsProbe.errors.length) fact("probe JS exceptions", hlsProbe.errors.slice(0, 3).join(" | "));
  } finally {
    try { if (cdp) cdp.close(); } catch (_e) { /* ignore */ }
    if (edge) {
      try { spawnSyncKill(edge.child.pid); } catch (_e) { /* ignore */ }
      try { fs.rmSync(edge.udd, { recursive: true, force: true }); } catch (_e) { /* ignore */ }
    }
    for (const srv of [mediaSrv, distSrv, probeSrv].filter(Boolean)) {
      try { srv.close(); } catch (_e) { /* ignore */ }
    }
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch (_e) { /* ignore */ }
  }

  const failed = results.filter((r) => !r.pass);
  console.log(`\nPhase 33 browser check: ${results.length - failed.length}/${results.length} passed`);
  if (failed.length) process.exitCode = 1;
}

function spawnSyncKill(pid) {
  const { spawnSync } = require("child_process");
  if (process.platform === "win32") spawnSync("taskkill", ["/F", "/T", "/PID", String(pid)], { stdio: "ignore" });
  else try { process.kill(pid, "SIGKILL"); } catch (_e) { /* ignore */ }
}

main().catch((err) => { console.error("Phase 33 browser check failed:", err); process.exitCode = 1; });
